export class Hasher {
    constructor(a = 11, b = 13, c = 17) {
        this.a = a;
        this.b = b;
        this.c = c;
        this._hash = 0;
    }
    addInt(i) {
        this._hash = (this._hash * this.a + i * this.b + this.c) & 0xFFFFFFFF;
    }
    add(buffer) {
        const a = new Uint8Array(buffer);
        for (const i of a) {
            this.addInt(i);
        }
        return this;
    }
    addBoolean(b) {
        this.addInt(b ? 1 : 0);
        return this;
    }
    addNumbers(...ns) {
        const array = new Float64Array(ns);
        return this.add(array.buffer);
    }
    addNumber(n) {
        const array = new Float64Array(1);
        array[0] = n;
        return this.add(array.buffer);
    }
    addString(s) {
        return this.add(new Uint32Array([...s].map(c => c.codePointAt(0) ?? 0)).buffer);
    }
    get hash() {
        return this._hash;
    }
}
export function hash(value) {
    return doHash(value);
}
export function doHash(value, hasher = new Hasher()) {
    if (value instanceof Array) {
        for (const v of value) {
            doHash(v, hasher);
        }
        return hasher.hash;
    }
    switch (typeof value) {
        case "boolean": return hasher.addBoolean(value).hash;
        case "number": return hasher.addNumber(value).hash;
        case "string": return hasher.addString(value).hash;
        case "object": {
            if ("hash" in value && typeof value.hash === "number") {
                return doHash(value.hash, hasher);
            }
            for (const [k, v] of Object.entries(value)) {
                hasher.addString(k);
                doHash(v, hasher);
            }
            return hasher.hash;
        }
    }
}
